/* prog51_union_find.c
 *
 * Re‑implementation of the original program (identified as prog51_union_find)
 * whose behaviour is completely described by the decompiled main() above.
 *
 * The program implements a tiny disjoint‑set (union‑find) data structure for
 * at most 10 elements (indices 0 … 9).  It reads a sequence of commands from
 * the command line (argv) and prints the results to stdout.
 *
 * Supported commands (case‑sensitive, first character only is examined):
 *
 *   U a b   – union the sets containing a and b.
 *             Prints:  "UNION %ld %ld\n"
 *
 *   F a     – find the representative (root) of element a.
 *             Prints:  "FIND %ld=%d\n"
 *
 *   C a b   – test whether a and b are in the same set.
 *             Prints:  "YES"  or  "NO"
 *
 * For any command whose numeric arguments are not in the range [0,9] the
 * program prints "INVALID".  If the program is invoked without any command
 * (argc < 2) it prints "NOOP".  After processing all commands the program
 * terminates with exit status 0.
 *
 * The implementation follows the logic of the original binary but is written
 * in clear, idiomatic C.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_ELEMS 10

static int parent[MAX_ELEMS];
static int rankv[MAX_ELEMS];

/* Find with path compression */
static int find_set(int x)
{
    if (parent[x] != x)
        parent[x] = find_set(parent[x]);
    return parent[x];
}

/* Union by rank */
static void union_set(int x, int y)
{
    int rx = find_set(x);
    int ry = find_set(y);
    if (rx == ry)
        return;

    if (rankv[rx] < rankv[ry]) {
        parent[rx] = ry;
    } else if (rankv[rx] > rankv[ry]) {
        parent[ry] = rx;
    } else {
        parent[ry] = rx;
        rankv[rx]++;
    }
}

/* Helper: convert string to long, detect errors */
static long parse_long(const char *s, int *ok)
{
    char *endptr;
    long v = strtol(s, &endptr, 10);
    if (endptr == s || *endptr != '\0')
        *ok = 0;
    else
        *ok = 1;
    return v;
}

/* Helper: check that a value is a valid element index */
static int valid_index(long v)
{
    return (v >= 0 && v < MAX_ELEMS);
}

int main(int argc, char *argv[])
{
    /* initialise the disjoint‑set structure */
    for (int i = 0; i < MAX_ELEMS; ++i) {
        parent[i] = i;
        rankv[i] = 0;
    }

    if (argc < 2) {
        puts("NOOP");
        return 0;
    }

    int i = 1;                     /* current argument index */
    while (i < argc) {
        const char *cmd = argv[i];

        if (cmd[0] == 'U') {               /* UNION command */
            if (i + 2 >= argc) {           /* not enough arguments */
                puts("INVALID");
                break;
            }
            int ok1, ok2;
            long a = parse_long(argv[i + 1], &ok1);
            long b = parse_long(argv[i + 2], &ok2);
            if (ok1 && ok2 && valid_index(a) && valid_index(b)) {
                union_set((int)a, (int)b);
                printf("UNION %ld %ld\n", a, b);
            } else {
                puts("INVALID");
            }
            i += 3;
        }
        else if (cmd[0] == 'F') {          /* FIND command */
            if (i + 1 >= argc) {
                puts("INVALID");
                break;
            }
            int ok;
            long a = parse_long(argv[i + 1], &ok);
            if (ok && valid_index(a)) {
                int root = find_set((int)a);
                printf("FIND %ld=%d\n", a, root);
            } else {
                puts("INVALID");
            }
            i += 2;
        }
        else if (cmd[0] == 'C') {          /* CONNECTED / CHECK command */
            if (i + 2 >= argc) {
                puts("INVALID");
                break;
            }
            int ok1, ok2;
            long a = parse_long(argv[i + 1], &ok1);
            long b = parse_long(argv[i + 2], &ok2);
            if (ok1 && ok2 && valid_index(a) && valid_index(b)) {
                int ra = find_set((int)a);
                int rb = find_set((int)b);
                puts(ra == rb ? "YES" : "NO");
            } else {
                puts("INVALID");
            }
            i += 3;
        }
        else {                              /* unknown command */
            puts("INVALID");
            i++;    /* skip the unknown token and continue */
        }
    }

    return 0;
}
